        --local lockDesc = GameUtils.GetUnlockDescrBySystemTogId(self.data.id)
        --if isSystemUnLock then
            --if not isJumpUnLock and self.data.id == Constants.SystemToggleIds.Id2015  then
                --local _
                --_,lockDesc = OverseaTowerUtils.IsFunctionUnlock(checkInt(row:Get("ID")))
            --end
        --end
        --CfUtils.FillText(self.TxtLock,lockDesc)
    else
        CfUtils.SetUISwitchImage(self.BtnBg,1)
        CfUtils.FillImage(self.ImgIconOn,self.data.icon)
       self:RefreshUnLockShow(isHaveReward)
    end
end

function ProcessOverviewCell:RefreshUnLockShow(isHaveReward)
    ---@type PlayerComponent
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local timeInfo = playerComp:GetProgressInfoById(self.data.id) - os.time()
    if self.data.ifPresent then
        CfUtils.SetActive(self.ImgReward,isHaveReward)
    end
    if not isNull(timeInfo) and timeInfo > 0 then
        KTool.SetActive(self.TxtTime.gameObject,true)
        KTool.SetActive(self.StatusGroup.gameObject,false)
        KTool.SetActive(self.UIFX_BtnBg_flow.gameObject,true)
        CfUtils.PlayAnimation(self.OpenGroup,"UIHomeView_ProcesOverViewPopUp_Cell_OpenGroup_Idle")
        self:RemoveCdTimer(self.timer)
        CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS(checkNumber(timeInfo)))
        self.timer = CDTimerModule:AddCD(1, function(count, t)
            if count > 0 then
                CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS(checkNumber(count)))
            else
                CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS(checkNumber(0)))
                CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
                self.Timer = nil
                self:RefreshUnLockShow()
                if self.callBack then
                    self.callBack()
                end
            end
        end,timeInfo, false, true)
    else
        KTool.SetActive(self.TxtTime.gameObject,false)
        KTool.SetActive(self.StatusGroup.gameObject,true)
        KTool.SetActive(self.UIFX_BtnBg_flow.gameObject,false)
        CfUtils.FillText(self.TxtStatus,self.data.desc)
        CfUtils.PlayAnimation(self.OpenGroup,"UIHomeView_ProcesOverViewPopUp_Cell_OpenGroup_Activate")
    end
end

function ProcessOverviewCell:RemoveCdTimer(timer)
    if not isNull(timer) then
        CDTimerModule:RemoveCD(timer)
        timer = nil
    end
end

function ProcessOverviewCell:PlayAni(aniName,delayIndex)
    CfUtils.PlayAnimation(self.controller,"UI_Common_List_Cell_Hide")
    if not isNull(delayIndex) then
        CfUtils.PlayDelayShowAnimate(self.controller.gameObject, checkInt(delayIndex), 0.06,nil,aniName)
    end
end

function ProcessOverviewCell:PlayAniEnd(aniName,delayIndex)
    CfUtils.PlayDelayShowAnimate(self.controller.gameObject, checkInt(delayIndex), 0.06,nil,aniName)
end

function ProcessOverviewCell:OnBtnItemClick()
    local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(self.data.openType)
    local isJumpUnLock = GoodsConfMgr:GetInstance():CheckIsCanJump(row, false)
    local isUnLock = GameUtils.IsUnlockedBySystemTogId(self.data.id)
    if isUnLock then
        if self.data.id == Constants.SystemToggleIds.Id2015  then
            if isJumpUnLock then
                GoodsConfMgr:GetInstance():ExecuteJump(row, {})
                if self.clickCallBack then
                    self.clickCallBack()
                end
            else
                local _ ,lockDesc = OverseaTowerUtils.IsFunctionUnlock(checkInt(row:Get("ID")))
                GameUtils.Toast(lockDesc)
            end
        else
            local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(self.data.openType)
            GoodsConfMgr:GetInstance():ExecuteJump(row, {})
            if self.clickCallBack then
                self.clickCallBack()
            end
        end
    else
        local lockDesc = GameUtils.GetUnlockDescrBySystemTogId(self.data.id)
        GameUtils.Toast(lockDesc)
    end

end

function ProcessOverviewCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:RemoveCdTimer(self.timer)
    self:Delete()
end

return ProcessOverviewCell